'use client';

import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode, type SetStateAction } from 'react';
import { ArrowDownToLine, ArrowRight, ArrowUpRight, Bell, BookOpen, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, Clock3, CreditCard, ExternalLink, FolderOpen, Globe2, History, LayoutDashboard, Link2, LoaderCircle, LogOut, Menu, MoreHorizontal, Package, Plus, Search, Send, Settings, ShieldCheck, SlidersHorizontal, Sparkles, Store, Users, X, Zap, CircleAlert, Pencil, Trash2 } from 'lucide-react';
import { can, type Role } from '@/lib/permissions';
import { type Context, type Snapshot, type AdminData, type Plan, type Restaurant, type Product, type Category, type Extra, type Hour, demoContext, makeDemo, emptySnapshot, emptyAdmin, money, date, weekdays } from '@/lib/data';

const navigation=[
 {id:'dashboard',label:'Visão geral',icon:LayoutDashboard,section:'PRINCIPAL'},
 {id:'products',label:'Produtos',icon:Package,section:'CARDÁPIO'},
 {id:'categories',label:'Categorias',icon:FolderOpen},
 {id:'extras',label:'Complementos',icon:SlidersHorizontal},
 {id:'hours',label:'Horários',icon:Clock3},
 {id:'integrations',label:'Integrações',icon:Link2,section:'CANAIS DE VENDA'},
 {id:'publication',label:'Publicação',icon:Send},
 {id:'history',label:'Histórico',icon:History},
 {id:'settings',label:'Configurações',icon:Settings,section:'ESTABELECIMENTO'},
];
const adminNavigation=[{id:'admin-restaurants',label:'Restaurantes',icon:Store},{id:'admin-users',label:'Usuários e acessos',icon:Users},{id:'admin-plans',label:'Planos e assinaturas',icon:CreditCard},{id:'admin-usage',label:'Utilização',icon:LayoutDashboard},{id:'admin-integrations',label:'Integrações',icon:Link2},{id:'admin-errors',label:'Histórico de erros',icon:CircleAlert}];
type EditRow=Partial<Product & Category & Extra & Hour & Restaurant & Plan>;
type Drawer={type:string;row?:EditRow};
async function request<T>(url:string,method='GET',body?:unknown):Promise<T> {
 const response=await fetch(url,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'});
 const value=await response.json(); if(!response.ok) throw new Error(value.error??'Não foi possível concluir a operação.'); return value;
}
function Badge({children,tone='green'}:{children:ReactNode;tone?:string}) {return <span className={`badge ${tone}`}><span/>{children}</span>;}
function Empty({title='Nada por aqui ainda',description='Os registros aparecerão aqui assim que você começar.',action}:{title?:string;description?:string;action?:ReactNode}) {return <div className="empty"><div className="empty-icon"><FolderOpen size={25}/></div><h3>{title}</h3><p>{description}</p>{action}</div>;}
function Platform({provider,small=false}:{provider:string;small?:boolean}) {return <span className={`platform ${provider==='ifood'?'ifood':'food99'} ${small?'small':''}`}>{provider==='ifood'?'iFood':'99'}{provider!=='ifood'&&!small&&<small>Food</small>}</span>;}
function Bowl() {return <svg className="bowl-art" viewBox="0 0 330 220" aria-hidden="true"><defs><linearGradient id="bowl" x2="0" y2="1"><stop stopColor="#ffffff"/><stop offset="1" stopColor="#dfcffa"/></linearGradient><linearGradient id="acai" x2=".8" y2="1"><stop stopColor="#703c91"/><stop offset="1" stopColor="#331344"/></linearGradient></defs><ellipse cx="170" cy="198" rx="105" ry="12" fill="#381269" opacity=".25"/><path d="M67 89h204c-10 78-42 108-101 108S77 167 67 89" fill="url(#bowl)"/><ellipse cx="169" cy="91" rx="104" ry="43" fill="#fdf9ff"/><ellipse cx="169" cy="89" rx="95" ry="35" fill="url(#acai)"/><path d="M84 90c25-22 38-18 52-12s29 15 51 10 42-12 65 1" fill="none" stroke="#9153ac" strokeWidth="7" strokeLinecap="round"/>{[0,1,2,3].map(i=><g key={i} transform={`translate(${133+i*21} ${58+i*4}) rotate(${i*14})`}><ellipse rx="16" ry="10" fill="#f4e0a5"/><ellipse rx="11" ry="6" fill="#fff0c6"/><path d="M-4-3l4 6 5-6" stroke="#c2a16b" fill="none" strokeWidth="1.5"/></g>)}<g transform="translate(105 83) rotate(-20)"><path d="M-19-6c1-16 36-16 38 0 0 12-13 29-19 30S-18 8-19-6" fill="#e55879"/><path d="M-8-16l8 7 12-8-9-3z" fill="#7ca472"/><path d="M-10-2l1 3m12-4 1 3m8 2-1 3m-13 4 1 3m8 1-1 3" stroke="#ffe8a4" strokeWidth="2"/></g><g fill="#ba92cd"><circle cx="211" cy="97" r="4"/><circle cx="224" cy="89" r="3"/><circle cx="231" cy="98" r="4"/><circle cx="209" cy="109" r="3"/><circle cx="225" cy="109" r="3"/></g><path d="M244 73l32-55c4-6 14 0 11 5l-33 57" fill="#d8c1ed"/><path d="M119 152c18 12 37 15 55 13" stroke="white" strokeWidth="5" opacity=".8" strokeLinecap="round"/><text x="171" y="149" textAnchor="middle" fontSize="23" fontWeight="800" fontFamily="Arial" fill="#6d3a99">willd.</text><g fill="#e5c9ff"><path d="M57 39l3 8 8 3-8 3-3 8-3-8-8-3 8-3z"/><path d="M283 135l2 6 6 2-6 2-2 6-2-6-6-2 6-2z"/></g></svg>;}

export default function Hub({demo}:{demo:boolean}) {
 const [context,setContext]=useState<Context|null>(demo?demoContext:null);
 const [store,setStore]=useState<Snapshot>(emptySnapshot);
 const [adminData,setAdminData]=useState<AdminData>(emptyAdmin);
 const [restaurantId,setRestaurantId]=useState(demo?demoContext.restaurants[0].id:'');
 const data=useMemo(()=>{
  if(!demo)return store;
  return Object.fromEntries(Object.entries(store).map(([key,rows])=>[key,rows.filter((r:{restaurant_id:string})=>r.restaurant_id===restaurantId)])) as Snapshot;
 },[store,restaurantId,demo]);
 function setData(update:SetStateAction<Snapshot>){
  setStore(previous=>{
   if(!demo)return typeof update==='function'?update(previous):update;
   const scoped=Object.fromEntries(Object.entries(previous).map(([key,rows])=>[key,rows.filter((r:{restaurant_id:string})=>r.restaurant_id===restaurantId)])) as Snapshot;
   const next=typeof update==='function'?update(scoped):update;
   return Object.fromEntries(Object.keys(previous).map(key=>[key,[...previous[key as keyof Snapshot].filter(r=>r.restaurant_id!==restaurantId),...next[key as keyof Snapshot]]])) as Snapshot;
  });
 }
 const [view,setView]=useState('dashboard'); const [admin,setAdmin]=useState(false);
 const [mobile,setMobile]=useState(false); const [busy,setBusy]=useState(false); const [loading,setLoading]=useState(true);
 const [error,setError]=useState(''); const [toast,setToast]=useState(''); const [search,setSearch]=useState(''); const [category,setCategory]=useState('all');
 const [drawer,setDrawer]=useState<Drawer|null>(null); const [provider,setProvider]=useState<'ifood'|'99food'>('ifood');
 const [notification,setNotification]=useState(false); const [help,setHelp]=useState(false); const [loggedOut,setLoggedOut]=useState(false);
 const requestVersion=useRef(0); const toastTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
 const restaurant=context?.restaurants.find(r=>r.id===restaurantId);
 const role:Role=context?.user.platform_role==='SUPER_ADMIN'||(demo&&admin)?'SUPER_ADMIN':context?.memberships.find(m=>m.restaurant_id===restaurantId)?.role??'RESTAURANT_EMPLOYEE';
 const subscription=data.subscriptions[0]; const plan=context?.plans.find(p=>p.id===subscription?.plan_id);
 const notify=(text:string)=>{setToast(text);if(toastTimer.current) clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),5500);};
 function navigate(next:string){setView(next);setSearch('');setCategory('all');setMobile(false);setError('');}
 async function loadContext(){const value=await request<Context>('/api/context');setContext(value);setRestaurantId(current=>value.restaurants.some(r=>r.id===current)?current:value.restaurants[0]?.id??'');return value;}
 async function loadTenant(id:string) {
  const version=++requestVersion.current;
  const resources=Object.keys(emptySnapshot) as (keyof Snapshot)[];
  const next={...emptySnapshot};
  await Promise.all(resources.map(async resource=>{
   if(resource==='memberships'&&!can(role,'members'))return;
   const rows=await request(`/api/restaurants/${id}/${resource}`);
   Object.assign(next,{[resource]:rows});
  }));
  if(version===requestVersion.current)setData(next);
 }
 async function loadAdmin(){const next={...emptyAdmin};await Promise.all(Object.keys(emptyAdmin).map(async key=>Object.assign(next,{[key]:await request(`/api/admin/${key}`)})));setAdminData(next);}
 useEffect(()=>{
  if(demo){
   try{const saved=localStorage.getItem('willd-demo-v1');if(saved){const parsed=JSON.parse(saved);setStore(parsed.data);setContext(parsed.context);}else setStore(makeDemo());}catch{setStore(makeDemo());}
   setLoading(false);
  }else{loadContext().catch(e=>{setError(e.message);setLoggedOut(true);}).finally(()=>setLoading(false));}
  return()=>{if(toastTimer.current)clearTimeout(toastTimer.current);};
 // Initial session request must run once; tenant changes are loaded by the following effect.
 // eslint-disable-next-line react-hooks/exhaustive-deps
 },[demo]);
 useEffect(()=>{
  if(demo||!restaurantId)return;
  setLoading(true);setData(emptySnapshot);loadTenant(restaurantId).catch(e=>setError(e.message)).finally(()=>setLoading(false));
 // eslint-disable-next-line react-hooks/exhaustive-deps
 },[restaurantId,demo,role]);
 useEffect(()=>{if(demo&&!loading&&context){try{localStorage.setItem('willd-demo-v1',JSON.stringify({data:store,context}));}catch{setError('O navegador não permitiu salvar a demonstração. As alterações permanecerão apenas nesta sessão.');}}},[store,context,demo,loading]);
 useEffect(()=>{
  if(!drawer&&!help)return;
  const previous=document.activeElement as HTMLElement|null;
  const oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';
  const dialog=document.querySelector<HTMLElement>('[role="dialog"]');
  const elements=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],[tabindex="0"]')??[]);
  (dialog?.querySelector<HTMLElement>('input,select,textarea')??elements()[0])?.focus();
  const listener=(event:KeyboardEvent)=>{
   if(event.key==='Escape'&&!busy){setDrawer(null);setHelp(false);}
   if(event.key==='Tab'){const focusable=elements();const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  };
  document.addEventListener('keydown',listener);
  return()=>{document.body.style.overflow=oldOverflow;document.removeEventListener('keydown',listener);previous?.focus();};
 },[drawer,help,busy]);
 useEffect(()=>{
  if(!admin)return;
  if(demo)setAdminData({restaurants:context?.restaurants??[],profiles:context?[context.user]:[],memberships:context?.memberships??[],plans:context?.plans??[],subscriptions:store.subscriptions,integrations:store.integrations,publications:store.publications,error_logs:[],audit_logs:store.audit_logs});
  else{setLoading(true);loadAdmin().catch(e=>setError(e.message)).finally(()=>setLoading(false));}
 // eslint-disable-next-line react-hooks/exhaustive-deps
 },[admin,demo,context,store]);
 async function run(action:()=>Promise<void>){if(busy)return;setBusy(true);setError('');try{await action();}catch(e){setError(e instanceof Error?e.message:'Erro inesperado.');}finally{setBusy(false);}}
 async function refresh(){if(demo)return;if(admin)await loadAdmin();else if(restaurantId)await loadTenant(restaurantId);}
 function audit(entity:string,action:string){return {id:crypto.randomUUID(),restaurant_id:restaurantId,entity,action,created_at:new Date().toISOString()};}
 function checkDemoPlan(kind:'product'|'integration'|'publication'){
  if(!subscription||!['active','trialing'].includes(subscription.status)||new Date(subscription.current_period_end)<=new Date()||(subscription.status==='trialing'&&new Date(subscription.trial_ends_at??0)<=new Date()))throw new Error('A assinatura não está ativa. Revise seu plano.');
  if(kind==='product'&&data.products.length>=(plan?.product_limit??0))throw new Error('Limite de produtos do plano atingido.');
  if(kind==='integration'&&data.integrations.filter(i=>i.status==='simulated').length>=(plan?.integration_limit??0))throw new Error('Limite de integrações do plano atingido.');
  if(kind==='publication'&&data.publications.filter(p=>p.created_at.slice(0,7)===new Date().toISOString().slice(0,7)).length>=(plan?.publication_limit??0))throw new Error('Limite mensal de publicações atingido.');
 }
 async function saveForm(event:FormEvent<HTMLFormElement>){
  event.preventDefault();if(!drawer)return;const form=new FormData(event.currentTarget);const type=drawer.type;const row=drawer.row;
  const text=(key:string)=>String(form.get(key)??'').trim();
  await run(async()=>{
   let values:Record<string,unknown>={};
   if(['products','categories','extras'].includes(type)){
    if(text('name').length<2)throw new Error('Informe um nome com pelo menos 2 caracteres.');
    values={name:text('name'),active:form.has('active')};
    if(type==='products'||type==='extras')values.price=Number(text('price'));
    if(type==='products')values={...values,description:text('description'),emoji:text('emoji')||'🍇',category_id:text('category_id')||null};
    if(type==='categories')values={...values,description:text('description'),sort_order:Number(text('sort_order'))||0};
   }
   if(type==='hours'){values={weekday:Number(text('weekday')),opens_at:text('opens_at'),closes_at:text('closes_at'),closed:form.has('closed')};if(!values.closed&&text('opens_at')>=text('closes_at'))throw new Error('O fechamento deve ser após a abertura.');}
   if(type==='settings'){
    values={name:text('name'),email:text('email'),phone:text('phone'),address:text('address')};
    if(demo)setContext(c=>c?{...c,restaurants:c.restaurants.map(r=>r.id===restaurantId?{...r,...values}:r)}:c);
    else{await request(`/api/restaurants/${restaurantId}/settings`,'PATCH',values);await loadContext();}
   }else if(type==='restaurants'){
    values={name:text('name'),slug:text('slug'),email:text('email'),phone:text('phone'),address:text('address'),status:'active',plan_id:text('plan_id')};
    if(demo){const {plan_id,...details}=values;const id=crypto.randomUUID();setContext(c=>c?{...c,restaurants:[...c.restaurants,{id,...details} as Restaurant]}:c);const end=new Date(Date.now()+14*86400000).toISOString();setStore(d=>({...d,subscriptions:[...d.subscriptions,{id:crypto.randomUUID(),restaurant_id:id,plan_id:String(plan_id),status:'trialing',trial_ends_at:end,current_period_end:end}]}));}
    else{await request('/api/admin/restaurants','POST',values);await loadContext();}
   }else if(type==='plans'){
    values={id:row?.id,name:text('name'),monthly_price:Number(text('monthly_price')),product_limit:Number(text('product_limit')),publication_limit:Number(text('publication_limit')),integration_limit:Number(text('integration_limit')),trial_days:Number(text('trial_days')),features:text('features').split('\n').map(v=>v.trim()).filter(Boolean)};
    if(demo)setContext(c=>c?{...c,plans:c.plans.map(p=>p.id===row?.id?{...p,...values} as Plan:p)}:c);
    else{await request('/api/admin/plans','PATCH',values);await loadContext();}
   }else if(type==='memberships'){
    values={user_id:text('user_id'),role:text('role')};
    if(!/^[0-9a-f-]{36}$/i.test(String(values.user_id)))throw new Error('Informe o UUID do usuário cadastrado no Supabase Auth.');
    if(demo){const member={id:crypto.randomUUID(),restaurant_id:restaurantId,...values} as unknown as Snapshot['memberships'][number];setData(d=>({...d,memberships:[...d.memberships.filter(m=>m.user_id!==member.user_id),member],audit_logs:[audit(type,'UPDATE'),...d.audit_logs]}));setContext(c=>c?{...c,memberships:[...c.memberships.filter(m=>!(m.restaurant_id===restaurantId&&m.user_id===member.user_id)),member]}:c);}
    else await request(`/api/restaurants/${restaurantId}/memberships`,'POST',values);
   }else if(type==='subscriptions'){
    values={restaurant_id:text('restaurant_id'),plan_id:text('plan_id'),status:text('status'),current_period_end:new Date(text('current_period_end')).toISOString(),trial_ends_at:text('trial_ends_at')?new Date(text('trial_ends_at')).toISOString():null};
    if(demo)setStore(d=>({...d,subscriptions:[...d.subscriptions.filter(s=>s.restaurant_id!==values.restaurant_id),{id:crypto.randomUUID(),...values} as unknown as Snapshot['subscriptions'][number]]}));
    else await request('/api/admin/subscriptions','PATCH',values);
   }else{
    if(demo){
     if(type==='products'&&!row?.id)checkDemoPlan('product');
     if(type==='hours'&&data.hours.some(h=>h.weekday===values.weekday&&h.id!==row?.id))throw new Error('Já existe um horário para este dia. Edite o registro existente.');
     setData(d=>({...d,[type]:row?.id?(d[type as 'products'] as unknown as EditRow[]).map(r=>r.id===row.id?{...r,...values}:r):[...d[type as 'products'],{id:crypto.randomUUID(),restaurant_id:restaurantId,...values}],audit_logs:[audit(type,row?.id?'UPDATE':'INSERT'),...d.audit_logs]}));
    }else await request(`/api/restaurants/${restaurantId}/${type}`,row?.id?'PATCH':'POST',row?.id?{id:row.id,...values}:values);
   }
   await refresh();setDrawer(null);notify('Alterações salvas com sucesso.');
  });
 }
 async function removeRow(){if(!drawer?.row?.id||!window.confirm('Excluir este registro? Esta ação não pode ser desfeita.'))return;
  await run(async()=>{const {type,row}=drawer;if(demo){if(type==='categories'&&data.products.some(p=>p.category_id===row?.id))throw new Error('Esta categoria possui produtos. Mova os produtos antes de excluí-la.');setData(d=>({...d,[type]:d[type as 'products'].filter(r=>r.id!==row?.id),audit_logs:[audit(type,'DELETE'),...d.audit_logs]}));}else await request(`/api/restaurants/${restaurantId}/${type}`,'DELETE',{id:row?.id});await refresh();setDrawer(null);notify('Registro excluído.');});
 }
 async function connect(target:'ifood'|'99food',disconnect=false){await run(async()=>{
  if(demo){if(!disconnect&&!data.integrations.some(i=>i.provider===target&&i.status==='simulated'))checkDemoPlan('integration');setData(d=>({...d,integrations:[...d.integrations.filter(i=>i.provider!==target),{id:crypto.randomUUID(),restaurant_id:restaurantId,provider:target,status:disconnect?'disconnected':'simulated',mode:'simulated'}],audit_logs:[audit('integrations',disconnect?'DISCONNECT':'CONNECT'),...d.audit_logs]}));}
  else await request(`/api/restaurants/${restaurantId}/integrations`,disconnect?'DELETE':'POST',{provider:target});await refresh();notify(disconnect?'Integração desconectada.':'Conexão de teste criada. Nenhuma conta real foi conectada.');
 });}
 async function publish(){await run(async()=>{
  if(!data.products.some(p=>p.active))throw new Error('Cadastre ao menos um produto ativo.');
  if(!data.integrations.some(i=>i.provider===provider&&i.status==='simulated'))throw new Error('Conecte este canal na área de integrações.');
  if(demo){checkDemoPlan('publication');setData(d=>({...d,publications:[{id:crypto.randomUUID(),restaurant_id:restaurantId,provider,status:'simulated',product_count:d.products.filter(p=>p.active).length,created_at:new Date().toISOString(),request_id:crypto.randomUUID()},...d.publications],audit_logs:[audit('publications','INSERT'),...d.audit_logs]}));}
  else await request(`/api/restaurants/${restaurantId}/publications`,'POST',{provider,request_id:crypto.randomUUID()});
  await refresh();notify('Simulação concluída! O cardápio foi registrado no histórico.');
 });}
 async function toggleRestaurant(target:Restaurant){await run(async()=>{const status=target.status==='active'?'suspended':'active';if(demo)setContext(c=>c?{...c,restaurants:c.restaurants.map(r=>r.id===target.id?{...r,status}:r)}:c);else{await request('/api/admin/restaurants','PATCH',{id:target.id,status});await loadContext();}await refresh();notify(status==='active'?'Conta ativada.':'Conta suspensa. O acesso do restaurante foi bloqueado.');});}
 async function logout(){await run(async()=>{if(demo){notify('Esta é uma sessão de demonstração. Nenhuma conta está conectada.');return;}await request('/api/auth/logout','POST',{});setContext(null);setData(emptySnapshot);setLoggedOut(true);});}
 function exportHistory(){const rows=[['Data','Canal','Status','Produtos'],...data.publications.map(p=>[date(p.created_at),p.provider,p.status,String(p.product_count)])];const blob=new Blob(['\ufeff'+rows.map(row=>row.map(cell=>'"'+cell.replaceAll('"','""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='willd-publicacoes.csv';a.click();URL.revokeObjectURL(url);notify('Histórico exportado.');}
 const title=admin?adminNavigation.find(n=>n.id===view)?.label??'Administração':navigation.find(n=>n.id===view)?.label??'Visão geral';
 const descriptions:Record<string,string>={dashboard:'Tudo o que seu negócio precisa, em um só lugar.',products:'Organize os sabores que fazem parte do seu cardápio.',categories:'Um cardápio organizado começa pelas categorias.',extras:'Mais possibilidades para cada pedido.',hours:'Defina quando seu estabelecimento está disponível.',integrations:'Conecte seu cardápio aos seus canais de delivery.',publication:'Seu cardápio atualizado, pronto para ir mais longe.',history:'Acompanhe cada atualização do seu cardápio.',settings:'Cuide dos detalhes do seu estabelecimento.'};
 const productList=data.products.filter(p=>(category==='all'||p.category_id===category)&&`${p.name} ${p.description}`.toLowerCase().includes(search.toLowerCase()));
 const currentRoleName=role==='RESTAURANT_OWNER'?'Proprietário':role==='RESTAURANT_MANAGER'?'Gerente':role==='SUPER_ADMIN'?'Super administrador':'Funcionário';

 if(!demo&&(!context||loggedOut))return <div className="login-shell"><div className="login-story"><a className="brand light" href="/"><span className="brand-mark">w<span>↗</span></span>WillD <b>Hub</b></a><div><span className="eyebrow">MENOS TRABALHO. MAIS POSSIBILIDADES.</span><h1>Seu cardápio,<br/>em todo lugar.</h1><p>Concentre sua operação. Conecte seus canais.<br/>Abra espaço para o seu negócio crescer.</p><Bowl/></div><span>Feito para quem alimenta boas ideias.</span></div><main className="login-card"><div className="brand mobile-brand"><span className="brand-mark">w<span>↗</span></span>WillD <b>Hub</b></div><span className="eyebrow purple-text">BEM-VINDO AO SEU HUB</span><h2>Bom ter você aqui.</h2><p>Entre para gerenciar seu estabelecimento.</p>{error&&<div className="alert" role="alert">{error}</div>}<form onSubmit={e=>{e.preventDefault();const form=new FormData(e.currentTarget);run(async()=>{await request('/api/auth/login','POST',{email:form.get('email'),password:form.get('password')});await loadContext();setLoggedOut(false);});}}><label>E-mail<input type="email" name="email" autoComplete="username" placeholder="voce@restaurante.com.br" required/></label><label>Senha<input type="password" name="password" autoComplete="current-password" minLength={8} required/></label><button className="button primary full" disabled={busy||loading}>{busy?<LoaderCircle className="spin" size={18}/>:<>Entrar no WillD Hub <ArrowRight size={18}/></>}</button></form><p className="small muted">O acesso é fornecido pelo administrador do estabelecimento. Solicite a ele seu cadastro ou a recuperação de senha.</p></main></div>;

 return <div className="app-shell">
  {mobile&&<button className="sidebar-overlay" aria-label="Fechar menu" onClick={()=>setMobile(false)}/>}
  <aside className={`sidebar ${mobile?'open':''}`}>
   <a className="brand" href="/" aria-label="WillD Hub, início"><span className="brand-mark">w<span>↗</span></span>WillD <b>Hub</b><span className="brand-dot"/></a>
   <div className="restaurant-switch"><div className="restaurant-avatar">W</div><div><span>SEU ESTABELECIMENTO</span><strong>{restaurant?.name??'Selecione uma conta'}</strong></div><ChevronDown size={15}/><select aria-label="Selecionar estabelecimento" value={restaurantId} onChange={e=>{setRestaurantId(e.target.value);navigate('dashboard');setAdmin(false);}}>{context?.restaurants.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></div>
   <nav aria-label="Navegação principal">{(admin?adminNavigation:navigation).map(item=><div key={item.id}>{'section' in item&&item.section&&<p className="nav-section">{item.section}</p>}<button className={`nav-item ${view===item.id?'active':''}`} onClick={()=>navigate(item.id)}><item.icon size={19} strokeWidth={1.7}/><span>{item.label}</span>{item.id==='integrations'&&<span className="nav-count">{data.integrations.filter(i=>i.status==='simulated').length}</span>}{view===item.id&&<span className="nav-active-dot"/>}</button></div>)}</nav>
   <div className="sidebar-bottom"><div className="plan-box"><div><span className="plan-icon"><Zap size={17}/></span><strong>{plan?.name??'Seu plano'}</strong><span className="plan-pill">{subscription?.status==='trialing'?'TESTE':'PLANO'}</span></div><p>{data.products.length} de {plan?.product_limit??0} produtos utilizados</p><div className="progress"><i style={{width:`${Math.min(100,data.products.length/(plan?.product_limit??1)*100)}%`}}/></div><button onClick={()=>{setAdmin(false);navigate('settings');}}>Conhecer meu plano <ArrowUpRight size={14}/></button></div>
   {(demo||context?.user.platform_role==='SUPER_ADMIN')&&<button className="admin-link" onClick={()=>{setAdmin(!admin);navigate(admin?'dashboard':'admin-restaurants');}}><ShieldCheck size={17}/>{admin?'Voltar ao restaurante':demo?'Administração · demonstração':'Administração WillD'}<ArrowUpRight size={14}/></button>}
   <button className="help-link" onClick={()=>setHelp(true)}><CircleHelp size={17}/>Precisa de uma mão?<ArrowUpRight size={14}/></button>
   <button className="user-card" onClick={()=>{setAdmin(false);navigate('settings');}}><span className="user-avatar">{context?.user.name?.slice(0,1)||'W'}</span><span><strong>{context?.user.name||'Minha conta'}</strong><small>{currentRoleName}</small></span><MoreHorizontal size={18}/></button></div>
  </aside>
  <div className="workspace"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="Abrir menu" onClick={()=>setMobile(true)}><Menu size={22}/></button><span>{admin?'WillD Hub':'Meu estabelecimento'}</span><ChevronRight size={14}/><strong>{title}</strong></div><div className="topbar-right"><span className="environment"><span/>{demo?'Ambiente de demonstração':'Ambiente seguro'}</span><button className="icon-button notification-button" aria-label="Notificações" onClick={()=>setNotification(!notification)}><Bell size={19}/>{subscription?.status==='trialing'&&<i/>}</button><span className="top-divider"/><button className="top-avatar" aria-label="Minha conta" onClick={()=>{setAdmin(false);navigate('settings');}}>W</button></div>{notification&&<div className="notification-panel"><strong>Seu Hub em dia</strong><p>{subscription?.status==='trialing'?`Seu período de teste termina em ${new Date(subscription.trial_ends_at??'').toLocaleDateString('pt-BR')}.`:'Confira suas configurações de plano e integrações.'}</p><p>As conexões iFood e 99Food operam em modo simulado.</p><button className="text-button" onClick={()=>{setNotification(false);navigate('integrations');}}>Ver integrações <ArrowRight size={14}/></button></div>}</header>
  <main className="main-content">
   {demo&&<div className="demo-bar"><Sparkles size={14}/><span>Explore o WillD Hub. Os dados são demonstrativos e ficam apenas neste navegador.</span><button onClick={()=>{localStorage.removeItem('willd-demo-v1');setStore(makeDemo());setContext(demoContext);setRestaurantId(demoContext.restaurants[0].id);notify('Demonstração reiniciada.');}}>Reiniciar demo</button></div>}
   {error&&<div className="alert" role="alert"><CircleAlert size={18}/><span>{error}</span><button aria-label="Fechar aviso" onClick={()=>setError('')}><X size={16}/></button></div>}
   <div className="page-heading"><div><div className="page-overline">{admin?'CONTROLE DA PLATAFORMA':'SEU NEGÓCIO, CONECTADO'}</div><h1>{title}{view==='dashboard'&&<span className="heading-dot">.</span>}</h1><p>{admin?'Gerencie os estabelecimentos e acompanhe a plataforma.':descriptions[view]}</p></div><div className="page-actions">{view==='dashboard'&&<button className="button secondary" onClick={()=>navigate('history')}><History size={16}/>Ver histórico</button>}{['products','categories','extras','hours'].includes(view)&&can(role,'catalog')&&<button className="button primary" onClick={()=>setDrawer({type:view})}><Plus size={17}/>{view==='products'?'Novo produto':view==='categories'?'Nova categoria':view==='extras'?'Novo complemento':'Adicionar horário'}</button>}{view==='admin-restaurants'&&<button className="button primary" onClick={()=>setDrawer({type:'restaurants'})}><Plus size={17}/>Novo restaurante</button>}{view==='history'&&<button className="button secondary" onClick={exportHistory}><ArrowDownToLine size={16}/>Exportar CSV</button>}</div></div>
   {loading?<div className="loading"><LoaderCircle className="spin" size={27}/><p>Preparando seu Hub…</p></div>:restaurant?.status==='suspended'&&!admin&&role!=='SUPER_ADMIN'?<Empty title="Conta suspensa" description="Entre em contato com o administrador da plataforma para reativar o estabelecimento."/>:!restaurantId&&!admin?<Empty title="Seu acesso está pronto" description="Peça ao administrador para vincular sua conta a um estabelecimento."/>:<>
   {view==='dashboard'&&<>
    <section className="welcome-card"><div className="welcome-copy"><span className="welcome-label"><span/>O PRÓXIMO PASSO DO SEU NEGÓCIO</span><h2>Um cardápio.<br/>Todas as possibilidades.</h2><p>Do seu balcão para os apps de delivery.<br/>Gerencie tudo por aqui e foque no que faz de melhor.</p><button className="button white" onClick={()=>navigate('publication')}>Publicar meu cardápio <ArrowUpRight size={17}/></button></div><div className="welcome-visual"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><span className="visual-tag tag-one"><CheckCheck size={14}/>Tudo em um só lugar</span><Bowl/><span className="visual-tag tag-two"><span className="green-light"/>Seu cardápio conectado</span></div></section>
    <div className="stats-grid">{[
     {label:'Produtos no cardápio',value:data.products.length,detail:`${data.products.filter(p=>p.active).length} disponíveis para publicação`,icon:Package,tone:'purple',next:'products'},
     {label:'Categorias',value:data.categories.length,detail:'Um cardápio mais organizado',icon:FolderOpen,tone:'blue',next:'categories'},
     {label:'Canais conectados',value:`${data.integrations.filter(i=>i.status==='simulated').length}/2`,detail:'Conexões em modo simulado',icon:Link2,tone:'orange',next:'integrations'},
     {label:'Publicações neste mês',value:data.publications.filter(p=>p.created_at.slice(0,7)===new Date().toISOString().slice(0,7)).length,detail:`de ${plan?.publication_limit??0} disponíveis no plano`,icon:Send,tone:'green',next:'history'},
    ].map(s=><button className="stat-card" key={s.label} onClick={()=>navigate(s.next)}><div className="stat-top"><span>{s.label}</span><span className={`stat-icon ${s.tone}`}><s.icon size={18}/></span></div><strong>{s.value}</strong><small>{s.detail}</small></button>)}</div>
    <div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><h2>Seus canais de delivery</h2><p>Um olhar rápido nas suas conexões.</p></div><button className="text-button" onClick={()=>navigate('integrations')}>Gerenciar <ArrowRight size={14}/></button></div><div className="channel-list">{(['ifood','99food'] as const).map(p=>{const connected=data.integrations.some(i=>i.provider===p&&i.status==='simulated');return <div className="channel-row" key={p}><Platform provider={p}/><div><strong>{p==='ifood'?'iFood':'99Food'}</strong><span>{connected?'Pronto para simular publicações':'Conecte um novo canal de vendas'}</span></div><Badge tone={connected?'green':'gray'}>{connected?'Simulado':'Desconectado'}</Badge><button className="icon-button" aria-label={`Gerenciar ${p}`} onClick={()=>navigate('integrations')}><ChevronRight size={17}/></button></div>;})}</div><div className="panel-foot"><ShieldCheck size={15}/><span>Suas credenciais protegidas. Seu negócio em primeiro lugar.</span></div></section>
    <section className="panel activity-chart"><div className="panel-heading"><div><h2>Atividade do cardápio</h2><p>Publicações nos últimos 7 dias.</p></div><span className="chart-label"><i/>Publicações</span></div><div className="bar-chart">{Array.from({length:7},(_,i)=>{const day=new Date();day.setDate(day.getDate()-(6-i));const count=data.publications.filter(p=>new Date(p.created_at).toDateString()===day.toDateString()).length;const max=Math.max(2,...Array.from({length:7},(_,n)=>{const d=new Date();d.setDate(d.getDate()-n);return data.publications.filter(p=>new Date(p.created_at).toDateString()===d.toDateString()).length;}));return <div className="bar-column" key={i}><div className="bar-track"><span title={`${count} publicações`} style={{height:count?`${count/max*100}%`:'3px'}}><b>{count}</b></span></div><small>{day.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}</small></div>;})}</div></section></div>
    <div className="dashboard-grid bottom-grid"><section className="panel"><div className="panel-heading"><div><h2>Últimas publicações</h2><p>Cada atualização, um passo a mais.</p></div><button className="text-button" onClick={()=>navigate('history')}>Ver todas <ArrowRight size={14}/></button></div>{data.publications.length?<div className="recent-list">{data.publications.slice(0,3).map(p=><div className="recent-row" key={p.id}><span className="recent-icon"><Check size={17}/></span><div><strong>Cardápio simulado no {p.provider==='ifood'?'iFood':'99Food'}</strong><span>{p.product_count} produtos · {date(p.created_at)}</span></div><Badge tone="purple">Simulado</Badge></div>)}</div>:<Empty title="Sua primeira publicação começa aqui" description="Conecte um canal e simule o envio do seu cardápio."/>}</section><section className="tip-card"><div className="tip-icon"><Sparkles size={22}/></div><span className="eyebrow purple-text">DICA DO HUB</span><h2>Um bom cardápio<br/>abre o apetite.</h2><p>Nomes claros, descrições caprichadas e categorias organizadas ajudam seus clientes a escolher.</p><button className="text-button" onClick={()=>navigate('products')}>Dar uma olhada no cardápio <ArrowRight size={15}/></button></section></div>
   </>}
   {view==='products'&&<section className="panel catalog-panel"><div className="catalog-toolbar"><div className="tabs"><button className={category==='all'?'selected':''} onClick={()=>setCategory('all')}>Todos <span>{data.products.length}</span></button>{data.categories.map(c=><button key={c.id} className={category===c.id?'selected':''} onClick={()=>setCategory(c.id)}>{c.name}</button>)}</div><div className="search-box"><Search size={17}/><input aria-label="Buscar produtos" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar produto…"/></div></div><div className="product-grid">{productList.map(p=><article className="product-card" key={p.id}><div className={`product-art art-${p.emoji==='🍊'?'orange':p.emoji==='🍓'?'pink':p.emoji==='🍫'?'brown':'purple'}`}><span>{p.emoji}</span><Badge tone={p.active?'green':'gray'}>{p.active?'Ativo':'Pausado'}</Badge></div><div className="product-body"><span className="product-category">{data.categories.find(c=>c.id===p.category_id)?.name??'Sem categoria'}</span><h3>{p.name}</h3><p>{p.description||'Adicione uma descrição para seu produto.'}</p><div className="product-bottom"><strong>{money(p.price)}</strong>{can(role,'catalog')&&<button className="icon-button" aria-label={`Editar ${p.name}`} onClick={()=>setDrawer({type:'products',row:p})}><Pencil size={16}/></button>}</div></div></article>)}</div>{!productList.length&&<Empty title="Nenhum produto encontrado" description="Ajuste a busca ou adicione um novo produto."/>}<div className="table-footer">{productList.length} produtos encontrados<span>Seu próximo sucesso começa no cardápio.</span></div></section>}
   {(view==='categories'||view==='extras')&&<section className="panel"><div className="panel-heading"><h2>{view==='categories'?'Categorias do cardápio':'Complementos e adicionais'}</h2><span className="count-label">{data[view].length} registros</span></div><div className="table-wrap"><table><thead><tr><th>Nome</th><th>{view==='categories'?'Produtos':'Preço adicional'}</th><th>Status</th><th><span className="sr-only">Ações</span></th></tr></thead><tbody>{(view==='categories'?data.categories:data.extras).map(r=><tr key={r.id}><td><div className="table-name"><span className="table-symbol">{view==='categories'?<FolderOpen size={20}/>:<Plus size={20}/>}</span><div><strong>{r.name}</strong>{'description'in r&&<small>{r.description}</small>}</div></div></td><td>{view==='categories'?`${data.products.filter(p=>p.category_id===r.id).length} produtos`:money((r as Extra).price)}</td><td><Badge tone={r.active?'green':'gray'}>{r.active?'Ativo':'Pausado'}</Badge></td><td>{can(role,'catalog')&&<button className="button small-button secondary" onClick={()=>setDrawer({type:view,row:r})}><Pencil size={14}/>Editar</button>}</td></tr>)}</tbody></table></div>{!data[view].length&&<Empty/>}</section>}
   {view==='hours'&&<><div className="info-banner"><Clock3 size={19}/><div><strong>Seu horário, bem definido.</strong><p>Cadastre horários no fuso de São Paulo. Nesta versão, cada dia possui um intervalo que termina no mesmo dia.</p></div></div><section className="panel"><div className="table-wrap"><table><thead><tr><th>Dia da semana</th><th>Abertura</th><th>Fechamento</th><th>Status</th><th/></tr></thead><tbody>{[...data.hours].sort((a,b)=>a.weekday-b.weekday).map(h=><tr key={h.id}><td><strong>{weekdays[h.weekday]}</strong></td><td>{h.closed?'—':h.opens_at.slice(0,5)}</td><td>{h.closed?'—':h.closes_at.slice(0,5)}</td><td><Badge tone={h.closed?'gray':'green'}>{h.closed?'Fechado':'Atendimento'}</Badge></td><td>{can(role,'catalog')&&<button className="button secondary small-button" onClick={()=>setDrawer({type:'hours',row:h})}><Pencil size={14}/>Editar</button>}</td></tr>)}</tbody></table></div>{!data.hours.length&&<Empty title="Defina seus horários"/>}</section></>}
   {view==='integrations'&&<><div className="info-banner"><ShieldCheck size={20}/><div><strong>Um ambiente seguro para preparar suas conexões.</strong><p>Os conectores são simulados. A integração real depende de autorização, homologação e recursos disponíveis nas APIs de cada plataforma.</p></div></div><div className="integration-grid">{(['ifood','99food'] as const).map(p=>{const connected=data.integrations.some(i=>i.provider===p&&i.status==='simulated');return <section className="panel integration-card" key={p}><div className="integration-card-top"><Platform provider={p}/><Badge tone={connected?'green':'gray'}>{connected?'Simulado':'Desconectado'}</Badge></div><h2>{p==='ifood'?'iFood':'99Food'}</h2><p>Prepare seu cardápio para {p==='ifood'?'o iFood':'a 99Food'} com uma conexão independente e exclusiva do seu estabelecimento.</p><div className="integration-capabilities"><span><Check size={15}/>Validação do cardápio</span><span><Check size={15}/>Histórico de simulações</span><span><ShieldCheck size={15}/>Credenciais separadas por restaurante</span></div><div className="integration-note"><Sparkles size={15}/>Modo simulado · sem acesso à plataforma</div>{can(role,'credentials')?<button className={`button ${connected?'secondary':'primary'} full`} disabled={busy} onClick={()=>connect(p,connected)}>{connected?<><Link2 size={16}/>Desconectar simulação</>:<><Plus size={17}/>Conectar em modo de teste</>}</button>:<p className="small muted">Apenas o proprietário pode gerenciar esta conexão.</p>}</section>;})}</div></>}
   {view==='publication'&&<div className="publication-grid"><section className="panel publication-card"><span className="section-icon"><Send size={25}/></span><h2>Seu cardápio está pronto<br/>para o próximo passo.</h2><p>Escolha um canal e simule a publicação. Uma cópia dos produtos ativos será registrada no histórico.</p><label className="field-label">Canal de publicação</label><div className="provider-options">{(['ifood','99food'] as const).map(p=><button key={p} className={provider===p?'chosen':''} onClick={()=>setProvider(p)}><Platform provider={p} small/><strong>{p==='ifood'?'iFood':'99Food'}</strong><span className="radio-circle">{provider===p&&<i/>}</span></button>)}</div><div className="publish-summary"><span>Produtos disponíveis</span><strong>{data.products.filter(p=>p.active).length}</strong><span>Modo de publicação</span><Badge tone="purple">Simulação</Badge><span>Canal conectado</span><strong>{data.integrations.some(i=>i.provider===provider&&i.status==='simulated')?'Sim':'Não'}</strong></div><button className="button primary full" disabled={busy||!can(role,'publish')} onClick={publish}>{busy?<LoaderCircle className="spin" size={17}/>:<Send size={17}/>}Simular publicação</button><p className="fine-print">Nenhum produto será enviado para o aplicativo de delivery.</p></section><section className="panel checklist-card"><h2>Antes de publicar</h2>{[{title:'Organize seu cardápio',body:'Revise os nomes, descrições e preços.',done:data.products.length>0,next:'products'},{title:'Defina as categorias',body:'Ajude seu cliente a encontrar o que procura.',done:data.categories.length>0,next:'categories'},{title:'Conecte o canal',body:'Ative uma conexão simulada para testar.',done:data.integrations.some(i=>i.provider===provider&&i.status==='simulated'),next:'integrations'}].map((item,i)=><button className="checklist-item" key={i} onClick={()=>navigate(item.next)}><span className={item.done?'done':''}>{item.done?<Check size={16}/>:i+1}</span><div><strong>{item.title}</strong><p>{item.body}</p></div><ChevronRight size={16}/></button>)}<div className="checklist-note"><BookOpen size={20}/><p>As funcionalidades reais serão habilitadas após a aprovação de cada plataforma.</p></div></section></div>}
   {view==='history'&&<><section className="panel"><div className="panel-heading"><div><h2>Publicações do cardápio</h2><p>Até 200 registros mais recentes por estabelecimento.</p></div><Badge tone="purple">{data.publications.length} registros</Badge></div><div className="table-wrap"><table><thead><tr><th>Publicação</th><th>Canal</th><th>Produtos</th><th>Status</th></tr></thead><tbody>{data.publications.map(p=><tr key={p.id}><td><strong>{date(p.created_at)}</strong><small className="record-id">#{p.id.slice(0,8)}</small></td><td><span className="inline-platform"><Platform provider={p.provider} small/>{p.provider==='ifood'?'iFood':'99Food'}</span></td><td>{p.product_count} produtos</td><td><Badge tone={p.status==='failed'?'red':'purple'}>{p.status==='failed'?'Falhou':'Simulado'}</Badge></td></tr>)}</tbody></table></div>{!data.publications.length&&<Empty title="Nenhuma publicação ainda" description="Sua primeira simulação aparecerá aqui." action={<button className="button primary" onClick={()=>navigate('publication')}>Preparar publicação <ArrowRight size={16}/></button>}/>}</section><section className="panel audit-panel"><div className="panel-heading"><div><h2>Auditoria de alterações</h2><p>Ações importantes registradas pelo sistema.</p></div><ShieldCheck size={21}/></div>{data.audit_logs.length?<div className="audit-list">{data.audit_logs.slice(0,15).map(a=><div key={a.id}><span className="audit-dot"/><strong>{a.entity}</strong><span>{a.action}</span><time>{date(a.created_at)}</time></div>)}</div>:<Empty title="Nenhuma alteração registrada" description="As próximas alterações importantes aparecerão aqui."/>}</section></>}
   {view==='settings'&&<><div className="settings-grid"><section className="panel"><div className="panel-heading"><div><h2>Dados do estabelecimento</h2><p>A identidade do seu negócio no Hub.</p></div>{can(role,'settings')&&<button className="button secondary small-button" onClick={()=>setDrawer({type:'settings',row:restaurant})}><Pencil size={14}/>Editar</button>}</div><div className="restaurant-profile"><span className="large-avatar">W</span><div><h2>{restaurant?.name}</h2><p>{restaurant?.slug}</p></div><Badge tone={restaurant?.status==='active'?'green':'red'}>{restaurant?.status==='active'?'Ativo':'Suspenso'}</Badge></div><dl className="details-list"><dt>E-mail</dt><dd>{restaurant?.email}</dd><dt>Telefone</dt><dd>{restaurant?.phone||'Não informado'}</dd><dt>Endereço</dt><dd>{restaurant?.address||'Não informado'}</dd><dt>Identificador</dt><dd className="uuid">{restaurant?.id}</dd></dl></section><section className="panel current-plan"><div className="panel-heading"><div><h2>Seu plano</h2><p>Pronto para acompanhar seu crescimento.</p></div><Zap size={22}/></div><h3>{plan?.name??'Sem plano'}</h3><div className="plan-price">{money(plan?.monthly_price??0)}<span>/mês</span></div><Badge tone="purple">{subscription?.status==='trialing'?'Período de teste':subscription?.status==='active'?'Ativo':subscription?.status??'Não configurado'}</Badge><ul>{plan?.features.map(f=><li key={f}><Check size={15}/>{f}</li>)}</ul><p className="small muted">{subscription?.status==='trialing'?'Teste até':'Período até'} {subscription?new Date(subscription.current_period_end).toLocaleDateString('pt-BR'):'—'}. Nenhuma cobrança real é realizada nesta etapa.</p><button className="button secondary full" onClick={()=>setHelp(true)}>Consultar opções de plano <ArrowUpRight size={15}/></button></section></div>{can(role,'members')&&<section className="panel audit-panel"><div className="panel-heading"><div><h2>Equipe e permissões</h2><p>Usuários vinculados a este estabelecimento.</p></div><button className="button secondary small-button" onClick={()=>setDrawer({type:'memberships'})}><Plus size={15}/>Vincular usuário</button></div><div className="table-wrap"><table><thead><tr><th>Usuário</th><th>Perfil</th></tr></thead><tbody>{data.memberships.map(m=><tr key={m.id}><td className="uuid">{m.user_id===context?.user.id?`${context.user.name} (você)`:m.user_id}</td><td><Badge tone="purple">{m.role==='RESTAURANT_OWNER'?'Proprietário':m.role==='RESTAURANT_MANAGER'?'Gerente':'Funcionário'}</Badge></td></tr>)}</tbody></table></div></section>}<section className="panel audit-panel"><div className="panel-heading"><div><h2>Histórico de pagamentos</h2><p>Estrutura preparada para um futuro gateway. Sem cobranças nesta etapa.</p></div><CreditCard size={20}/></div>{data.payments.length?<div className="audit-list">{data.payments.map(p=><div key={p.id}><strong>{money(p.amount)}</strong><span>{p.status}</span><time>{date(p.created_at)}</time></div>)}</div>:<Empty title="Nenhum pagamento registrado" description="O período de demonstração não gera cobranças."/>}</section><div className="account-footer"><span><ShieldCheck size={16}/>Você está conectado como <strong>{currentRoleName}</strong></span><button className="button secondary" disabled={busy} onClick={logout}><LogOut size={16}/>Sair da conta</button></div></>}
   {view==='admin-restaurants'&&<section className="panel"><div className="panel-heading"><h2>Estabelecimentos cadastrados</h2><span className="count-label">{adminData.restaurants.length} restaurantes</span></div><div className="table-wrap"><table><thead><tr><th>Estabelecimento</th><th>Identificador</th><th>Status</th><th>Ações</th></tr></thead><tbody>{adminData.restaurants.map(r=><tr key={r.id}><td><strong>{r.name}</strong><small className="record-id">{r.email}</small></td><td className="uuid">{r.id.slice(0,8)}…</td><td><Badge tone={r.status==='active'?'green':'red'}>{r.status==='active'?'Ativo':'Suspenso'}</Badge></td><td><div className="row-actions"><button className="button secondary small-button" onClick={()=>{setRestaurantId(r.id);setAdmin(false);navigate('settings');}}>Gerenciar <ArrowRight size={14}/></button><button className="text-button" disabled={busy} onClick={()=>toggleRestaurant(r)}>{r.status==='active'?'Suspender':'Ativar'}</button></div></td></tr>)}</tbody></table></div></section>}
   {view==='admin-users'&&<section className="panel"><div className="panel-heading"><div><h2>Usuários da plataforma</h2><p>Vincule usuários e gerencie seus perfis nas configurações do restaurante.</p></div><Users size={22}/></div><div className="table-wrap"><table><thead><tr><th>Nome</th><th>Identificador</th><th>Perfil da plataforma</th><th>Vínculos</th></tr></thead><tbody>{adminData.profiles.map(p=><tr key={p.id}><td><strong>{p.name||'Sem nome'}</strong></td><td className="uuid">{p.id}</td><td><Badge tone="purple">{p.platform_role==='SUPER_ADMIN'?'Super administrador':'Usuário'}</Badge></td><td>{adminData.memberships.filter(m=>m.user_id===p.id).length}</td></tr>)}</tbody></table></div><div className="panel-foot"><ShieldCheck size={16}/>Novos usuários são convidados pelo Supabase Auth. Privilégios globais são concedidos apenas pelo operador do banco.</div></section>}
   {view==='admin-plans'&&<><div className="plans-grid">{context?.plans.map(p=><section key={p.id} className={`panel plan-card ${p.name==='Profissional'?'featured':''}`}><span className="eyebrow purple-text">{p.name==='Profissional'?'MAIS POSSIBILIDADES':'PLANO MENSAL'}</span><h2>{p.name}</h2><div className="plan-price">{money(p.monthly_price)}<span>/mês</span></div><ul>{p.features.map(f=><li key={f}><Check size={16}/>{f}</li>)}<li><Check size={16}/>{p.trial_days} dias de teste</li></ul><span className="small muted">Sem cobrança real nesta etapa.</span><button className="button secondary full" style={{marginTop:20}} onClick={()=>setDrawer({type:'plans',row:p})}><Pencil size={14}/>Editar plano</button></section>)}</div><section className="panel audit-panel"><div className="panel-heading"><h2>Assinaturas dos restaurantes</h2><button className="button secondary small-button" onClick={()=>setDrawer({type:'subscriptions'})}><Pencil size={14}/>Gerenciar assinatura</button></div><div className="table-wrap"><table><thead><tr><th>Restaurante</th><th>Plano</th><th>Status</th><th>Fim do período</th></tr></thead><tbody>{adminData.subscriptions.map(s=><tr key={s.id}><td>{adminData.restaurants.find(r=>r.id===s.restaurant_id)?.name??s.restaurant_id}</td><td>{context?.plans.find(p=>p.id===s.plan_id)?.name}</td><td><Badge tone={s.status==='active'?'green':'purple'}>{s.status}</Badge></td><td>{new Date(s.current_period_end).toLocaleDateString('pt-BR')}</td></tr>)}</tbody></table></div></section></>}
   {view==='admin-usage'&&<><div className="stats-grid">{[{label:'Restaurantes',value:adminData.restaurants.length,icon:Store},{label:'Contas ativas',value:adminData.restaurants.filter(r=>r.status==='active').length,icon:CheckCheck},{label:'Usuários cadastrados',value:adminData.profiles.length,icon:Users},{label:'Publicações carregadas',value:adminData.publications.length,icon:Send}].map(s=><div className="stat-card" key={s.label}><div className="stat-top"><span>{s.label}</span><span className="stat-icon purple"><s.icon size={18}/></span></div><strong>{s.value}</strong><small>Dados de utilização da plataforma</small></div>)}</div><div className="info-banner"><CircleAlert size={20}/><p>Esta visão usa até 500 registros de cada recurso. Para escala de produção, implemente agregações e paginação no servidor.</p></div><section className="panel"><div className="panel-heading"><h2>Auditoria da plataforma</h2></div><div className="audit-list">{adminData.audit_logs.slice(0,20).map(a=><div key={a.id}><span className="audit-dot"/><strong>{a.entity}</strong><span>{a.action}</span><time>{date(a.created_at)}</time></div>)}</div>{!adminData.audit_logs.length&&<Empty/>}</section></>}
   {view==='admin-integrations'&&<section className="panel"><div className="panel-heading"><h2>Conexões por estabelecimento</h2><Badge tone="purple">Modo simulado</Badge></div><div className="table-wrap"><table><thead><tr><th>Estabelecimento</th><th>Canal</th><th>Status</th></tr></thead><tbody>{adminData.integrations.map(i=><tr key={i.id}><td>{adminData.restaurants.find(r=>r.id===i.restaurant_id)?.name??i.restaurant_id}</td><td><Platform provider={i.provider} small/></td><td><Badge tone={i.status==='simulated'?'green':'gray'}>{i.status==='simulated'?'Simulado':'Desconectado'}</Badge></td></tr>)}</tbody></table></div>{!adminData.integrations.length&&<Empty/>}</section>}
   {view==='admin-errors'&&<section className="panel"><div className="panel-heading"><h2>Erros de integração</h2><span className="count-label">{adminData.error_logs.length} registros</span></div>{adminData.error_logs.length?<div className="table-wrap"><table><thead><tr><th>Data</th><th>Origem</th><th>Restaurante</th><th>Mensagem</th></tr></thead><tbody>{adminData.error_logs.map(e=><tr key={e.id}><td>{date(e.created_at)}</td><td>{e.source}</td><td>{adminData.restaurants.find(r=>r.id===e.restaurant_id)?.name}</td><td>{e.message}</td></tr>)}</tbody></table></div>:<Empty title="Tudo tranquilo por aqui" description="Nenhum erro de integração foi registrado."/>}</section>}
   </>}
   <footer className="main-footer"><span>WillD Hub <i>·</i> Feito para o seu negócio ir além.</span><span><ShieldCheck size={13}/>Conectado com segurança</span></footer>
  </main></div>
  {toast&&<div className="toast" role="status"><span><Check size={17}/></span>{toast}<button aria-label="Fechar notificação" onClick={()=>setToast('')}><X size={16}/></button></div>}
  {drawer&&<div className="modal-overlay" onClick={()=>!busy&&setDrawer(null)}><section className="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title" onClick={e=>e.stopPropagation()} onKeyDown={e=>{if(e.key==='Escape'&&!busy)setDrawer(null);}}><div className="drawer-heading"><div><span className="eyebrow purple-text">CUIDE DOS DETALHES</span><h2 id="drawer-title">{drawer.type==='settings'?'Dados do estabelecimento':drawer.type==='memberships'?'Vincular usuário':drawer.type==='subscriptions'?'Gerenciar assinatura':drawer.type==='plans'?'Editar plano':`${drawer.row?.id?'Editar':'Adicionar'} ${drawer.type==='products'?'produto':drawer.type==='categories'?'categoria':drawer.type==='extras'?'complemento':drawer.type==='restaurants'?'restaurante':'horário'}`}</h2></div><button className="icon-button" aria-label="Fechar formulário" disabled={busy} onClick={()=>setDrawer(null)}><X size={21}/></button></div><form onSubmit={saveForm} key={`${drawer.type}-${drawer.row?.id??'new'}`}>
   {['products','categories','extras','settings','restaurants','plans'].includes(drawer.type)&&<label>Nome<input name="name" defaultValue={drawer.row?.name} required minLength={2} maxLength={120} autoFocus placeholder={drawer.type==='products'?'Ex.: Açaí especial 500ml':'Nome'}/></label>}
   {['products','categories'].includes(drawer.type)&&<label>Descrição<textarea name="description" defaultValue={drawer.row?.description} maxLength={drawer.type==='products'?1000:300} rows={3} placeholder="Conte um pouco mais…"/></label>}
   {['products','extras'].includes(drawer.type)&&<label>Preço (R$)<input name="price" type="number" step="0.01" min="0" max="100000" required defaultValue={drawer.row?.price??0}/></label>}
   {drawer.type==='products'&&<><label>Categoria<select name="category_id" defaultValue={drawer.row?.category_id??''}><option value="">Sem categoria</option>{data.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Ilustração<select name="emoji" defaultValue={drawer.row?.emoji??'🍇'}><option value="🍇">🍇 Açaí</option><option value="🍓">🍓 Frutas</option><option value="🍫">🍫 Chocolate</option><option value="💜">💜 Combo especial</option><option value="🍊">🍊 Bebida</option><option value="🍔">🍔 Lanche</option><option value="🍕">🍕 Pizza</option></select></label></>}
   {drawer.type==='plans'&&<><label>Preço mensal (R$)<input name="monthly_price" type="number" step="0.01" min="0" max="100000" defaultValue={drawer.row?.monthly_price} required/></label><div className="form-row"><label>Limite de produtos<input name="product_limit" type="number" min="1" max="100000" defaultValue={drawer.row?.product_limit} required/></label><label>Publicações por mês<input name="publication_limit" type="number" min="1" max="100000" defaultValue={drawer.row?.publication_limit} required/></label></div><div className="form-row"><label>Integrações<input name="integration_limit" type="number" min="1" max="2" defaultValue={drawer.row?.integration_limit} required/></label><label>Dias de teste<input name="trial_days" type="number" min="1" max="365" defaultValue={drawer.row?.trial_days} required/></label></div><label>Recursos (um por linha)<textarea name="features" rows={4} defaultValue={drawer.row?.features?.join('\n')}/></label><p className="small muted">Os novos limites se aplicam a todas as assinaturas deste plano. Nenhuma cobrança será realizada.</p></>}
   {drawer.type==='categories'&&<label>Ordem de exibição<input name="sort_order" type="number" min="0" defaultValue={drawer.row?.sort_order??0}/></label>}
   {['products','categories','extras'].includes(drawer.type)&&<label className="checkbox-label"><input name="active" type="checkbox" defaultChecked={drawer.row?.active??true}/><span>Disponível no cardápio</span></label>}
   {drawer.type==='hours'&&<><label>Dia da semana<select name="weekday" defaultValue={drawer.row?.weekday??1}>{weekdays.map((d,i)=><option key={d} value={i}>{d}</option>)}</select></label><div className="form-row"><label>Abertura<input name="opens_at" type="time" defaultValue={drawer.row?.opens_at?.slice(0,5)??'12:00'} required/></label><label>Fechamento<input name="closes_at" type="time" defaultValue={drawer.row?.closes_at?.slice(0,5)??'23:00'} required/></label></div><label className="checkbox-label"><input name="closed" type="checkbox" defaultChecked={drawer.row?.closed??false}/><span>Não funciona neste dia</span></label></>}
   {['settings','restaurants','plans'].includes(drawer.type)&&<><label>E-mail<input name="email" type="email" required defaultValue={drawer.row?.email} maxLength={254}/></label><label>Telefone<input name="phone" defaultValue={drawer.row?.phone} maxLength={30}/></label><label>Endereço<input name="address" defaultValue={drawer.row?.address} maxLength={300}/></label></>}
   {drawer.type==='restaurants'&&<><label>Identificador público<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" required maxLength={80} placeholder="nome-do-restaurante"/></label><label>Plano inicial<select name="plan_id">{context?.plans.map(p=><option key={p.id} value={p.id}>{p.name} · {money(p.monthly_price)}/mês</option>)}</select></label><p className="small muted">O restaurante inicia com o período de teste do plano. Vincule o proprietário após criar o estabelecimento.</p></>}
   {drawer.type==='memberships'&&<><div className="info-banner"><ShieldCheck size={20}/><p>Primeiro, convide o usuário pelo Supabase Auth. Depois, use o UUID para vinculá-lo ao restaurante.</p></div><label>UUID do usuário<input name="user_id" required placeholder="00000000-0000-0000-0000-000000000000"/></label><label>Perfil<select name="role"><option value="RESTAURANT_EMPLOYEE">Funcionário — somente leitura</option><option value="RESTAURANT_MANAGER">Gerente — cardápio e publicação</option>{role==='SUPER_ADMIN'&&<option value="RESTAURANT_OWNER">Proprietário — gestão do restaurante</option>}</select></label><p className="small muted">Se o usuário já está vinculado, o perfil será atualizado. Apenas o super administrador gerencia proprietários.</p></>}
   {drawer.type==='subscriptions'&&<><label>Restaurante<select name="restaurant_id" defaultValue={restaurantId}>{context?.restaurants.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label><label>Plano<select name="plan_id">{context?.plans.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>Status<select name="status"><option value="trialing">Teste</option><option value="active">Ativa</option><option value="past_due">Pendente</option><option value="canceled">Cancelada</option></select></label><label>Fim do período<input name="current_period_end" type="datetime-local" required/></label><label>Fim do teste<input name="trial_ends_at" type="datetime-local"/></label><p className="small muted">Esta alteração não realiza nenhuma cobrança.</p></>}
   {error&&<div className="alert" role="alert">{error}</div>}<div className="drawer-actions"><button className="button primary" disabled={busy} type="submit">{busy?<LoaderCircle size={17} className="spin"/>:<Check size={17}/>}Salvar alterações</button><button className="button secondary" type="button" disabled={busy} onClick={()=>setDrawer(null)}>Cancelar</button></div>{drawer.row?.id&&['products','categories','extras','hours'].includes(drawer.type)&&<button className="delete-button" type="button" disabled={busy} onClick={removeRow}><Trash2 size={15}/>Excluir registro</button>}
  </form></section></div>}
  {help&&<div className="modal-overlay" onClick={()=>setHelp(false)}><section className="help-modal panel" role="dialog" aria-modal="true" aria-labelledby="help-title" onClick={e=>e.stopPropagation()}><button className="icon-button close-help" aria-label="Fechar ajuda" onClick={()=>setHelp(false)}><X size={20}/></button><span className="section-icon"><CircleHelp size={26}/></span><h2 id="help-title">Vamos fazer seu negócio ir além.</h2><p>O WillD Hub está em sua primeira versão. Explore o cardápio, configure os horários e teste as publicações simuladas.</p><ul><li><strong>Planos:</strong> consulte o administrador da plataforma para alterar sua assinatura.</li><li><strong>Acesso:</strong> proprietários gerenciam a equipe; gerentes cuidam da operação; funcionários têm acesso de leitura.</li><li><strong>Integrações:</strong> as conexões reais dependem da aprovação de iFood e 99Food.</li></ul><p className="small muted">Para preparar a produção, consulte o guia em docs/PRODUCTION.md, incluído no projeto.</p><button className="button primary full" onClick={()=>setHelp(false)}>Entendi <Check size={17}/></button></section></div>}
 </div>;
}
